        // This needs a compare-and-set retry loop in case of concurrent updates.
        do {
            val c = this.callCounter.get()
            if (c == 0L) {
                throw IllegalStateException("${this.javaClass.simpleName} object has already been destroyed")
            }
            if (c == Long.MAX_VALUE) {
                throw IllegalStateException("${this.javaClass.simpleName} call counter would overflow")
            }
        } while (! this.callCounter.compareAndSet(c, c + 1L))
        // Now we can safely do the method call without the pointer being freed concurrently.
        try {
            return block(this.uniffiClonePointer())
        } finally {
            // This decrement always matches the increment we performed above.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable.clean()
            }
        }
    }

    // Use a static inner class instead of a closure so as not to accidentally
    // capture `this` as part of the cleanable's action.
    private class UniffiCleanAction(private val pointer: Pointer?) : Runnable {
        override fun run() {
            pointer?.let { ptr ->
                uniffiRustCall { status ->
                    UniffiLib.INSTANCE.uniffi_upspa_mobile_ffi_fn_free_transportport(ptr, status)
                }
            }
        }
    }

    fun uniffiClonePointer(): Pointer {
        return uniffiRustCall() { status ->
            UniffiLib.INSTANCE.uniffi_upspa_mobile_ffi_fn_clone_transportport(pointer!!, status)
        }
    }

    
    /**
     * Perform one request against a logical endpoint name (not a URL: routing is host policy).
     */
    @Throws(MobileException::class)override fun `send`(`endpoint`: kotlin.String, `payload`: kotlin.ByteArray): kotlin.ByteArray {
            return FfiConverterByteArray.lift(
    callWithPointer {
    uniffiRustCallWithError(MobileException) { _status ->
    UniffiLib.INSTANCE.uniffi_upspa_mobile_ffi_fn_method_transportport_send(
        it, FfiConverterString.lower(`endpoint`),FfiConverterByteArray.lower(`payload`),_status)
}
    }
    )
    }
    

    

    
    
    companion object
    
}


// Put the implementation in an object so we don't pollute the top-level namespace
internal object uniffiCallbackInterfaceTransportPort {
    internal object `send`: UniffiCallbackInterfaceTransportPortMethod0 {
        override fun callback(`uniffiHandle`: Long,`endpoint`: RustBuffer.ByValue,`payload`: RustBuffer.ByValue,`uniffiOutReturn`: RustBuffer,uniffiCallStatus: UniffiRustCallStatus,) {
            val uniffiObj = FfiConverterTypeTransportPort.handleMap.get(uniffiHandle)
            val makeCall = { ->
                uniffiObj.`send`(
                    FfiConverterString.lift(`endpoint`),
                    FfiConverterByteArray.lift(`payload`),
                )
            }
            val writeReturn = { value: kotlin.ByteArray -> uniffiOutReturn.setValue(FfiConverterByteArray.lower(value)) }
            uniffiTraitInterfaceCallWithError(
                uniffiCallStatus,
                makeCall,
                writeReturn,
                { e: MobileException -> FfiConverterTypeMobileError.lower(e) }
            )
        }
    }

    internal object uniffiFree: UniffiCallbackInterfaceFree {
        override fun callback(handle: Long) {
            FfiConverterTypeTransportPort.handleMap.remove(handle)
        }
    }

    internal var vtable = UniffiVTableCallbackInterfaceTransportPort.UniffiByValue(
        `send`,
        uniffiFree,
    )

    // Registers the foreign callback with the Rust side.
    // This method is generated for each callback interface.
    internal fun register(lib: UniffiLib) {
        lib.uniffi_upspa_mobile_ffi_fn_init_callback_vtable_transportport(vtable)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeTransportPort: FfiConverter<TransportPort, Pointer> {
    internal val handleMap = UniffiHandleMap<TransportPort>()

    override fun lower(value: TransportPort): Pointer {
        return Pointer(handleMap.insert(value))
    }

    override fun lift(value: Pointer): TransportPort {
        return TransportPortImpl(value)
    }

    override fun read(buf: ByteBuffer): TransportPort {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: TransportPort) = 8UL

    override fun write(value: TransportPort, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}



