    }
    
    class UnknownOperation(
        
        val `operation`: kotlin.String
        ) : MobileException() {
        override val message
            get() = "operation=${ `operation` }"
    }
    
    class OperationExpired(
        
        val `operation`: kotlin.String, 
        
        val `deadlineMillis`: kotlin.ULong, 
        
