        ) : MobileException() {
        override val message
            get() = "operation=${ `operation` }"
    }
    
    class OperationCancelled(
        
        val `operation`: kotlin.String
        ) : MobileException() {
        override val message
            get() = "operation=${ `operation` }"
    }
    
    class OutcomeMismatch(
        
        val `operation`: kotlin.String
        ) : MobileException() {
        override val message
            get() = "operation=${ `operation` }"
    }
    
    class Transport(
        
        val `reasonCode`: kotlin.String
        ) : MobileException() {
        override val message
            get() = "reasonCode=${ `reasonCode` }"
    }
    
    class SecureStorage(
        
        val `reasonCode`: kotlin.String
        ) : MobileException() {
        override val message
            get() = "reasonCode=${ `reasonCode` }"
    }
    
    class IdentityRejected(
        
        val `reasonCode`: kotlin.String
        ) : MobileException() {
        override val message
            get() = "reasonCode=${ `reasonCode` }"
    }
    
    class HostCallback(
        
